/**
 * The prebuilt avatar presets.
 *
 * Generated by outputs/gen_avatars.py. Edit the generator and re-run it — every
 * preset shares one piece of geometry, so a nudge here by hand is a nudge that
 * only lands on one avatar.
 */

import type { HairStyle } from './hair';

export type AvatarId =
  | 'boy-1'
  | 'boy-2'
  | 'boy-3'
  | 'boy-4'
  | 'girl-1'
  | 'girl-2'
  | 'girl-3'
  | 'girl-4';

export type AvatarGroup = 'boys' | 'girls';

/** Every shade the artwork needs, derived once by the generator. */
export type AvatarPalette = {
  skin: string;
  skinLight: string;
  skinShade: string;
  skinDeep: string;
  hair: string;
  hairLight: string;
  hairDark: string;
  shirt: string;
  shirtLight: string;
  shirtDark: string;
  bgLight: string;
  bgDeep: string;
  blush: string;
  brow: string;
  mouth: string;
};

export type AvatarPreset = {
  id: AvatarId;
  label: string;
  group: AvatarGroup;
  hair: HairStyle;
  palette: AvatarPalette;
};

