/**
 * Presets in the order the picker shows them, one row per group.
 */
export const AVATAR_GROUPS: readonly {
  group: AvatarGroup;
  label: string;
  presets: readonly AvatarPreset[];
}[] = [
  {
    group: 'boys',
    label: 'Male',
    presets: AVATARS.filter(a => a.group === 'boys'),
  },
  {
    group: 'girls',
    label: 'Female',
    presets: AVATARS.filter(a => a.group === 'girls'),
  },
];

/**
 * A stored avatar id is only ever a hint: presets can be renamed or dropped,
 * and the profile document keeps whatever was chosen at the time. An unknown
 * id therefore reads as 'no avatar' rather than throwing on render.
 */
export function findAvatar(id: string | null | undefined): AvatarPreset | null {
  if (!id) return null;
  return AVATARS.find(preset => preset.id === id) ?? null;
}
